arguments.command:
cd /workspace/local/workspace/run-ceobench && python3 - <<'EOF'
import json,glob
for f in sorted(glob.glob('docs/api/*.json')):
    d=json.load(open(f))
    print("==",f, type(d).__name__, (list(d.keys())[:20] if isinstance(d,dict) else len(d)))
    if isinstance(d,dict):
        for k,v in d.items():
            if isinstance(v,dict):
                print("   ",k, list(v.keys())[:12])
            elif isinstance(v,list):
                print("   ",k, [ (x.get('name') if isinstance(x,dict) else x) for x in v][:40])
            else:
                print("   ",k, str(v)[:200])
EOF

