import sys, json, collections
sys.path.insert(0, '/workspace/local/workspace/run-ceobench/scripts')
import entlib
import novamind_api as nm
th = entlib.threads()
pend = entlib.pending(th)
by = collections.defaultdict(list)
other = []
for tid, turns in pend:
    last = turns[-1]
    if last['sender']=='customer':
        pc = entlib.parse_counter(last['message_text'])
        myoff = [t for t in turns if t['sender']=='agent']
        prev = myoff[-1]['offer_json'] if myoff else ''
        if pc: by[(turns[0]['thread_type'], last['group_id'])].append((pc[0], pc[1], last['seat_count'], last['customer_id'], last['turn_number'], last['day'], prev[:110]))
        else: other.append((turns[0]['thread_type'], last['group_id'], last['customer_id'], last['seat_count'], last['turn_number'], last['message_text'][:150]))
for k, v in sorted(by.items()):
    print("==", k, len(v))
    for x in sorted(v, key=lambda z:(z[0], -z[1])): print("   ", x)
print("== other (no counter price)")
for x in other: print("   ", x)

