import sys, json, time
sys.path.insert(0, '/workspace/local/workspace/run-ceobench/scripts')
import entlib
import novamind_api as nm
base='/workspace/local/workspace/run-ceobench/notes/'
def show(label, r):
    print("##", label, "->", json.dumps(r)[:400])
for t in [7,1,2,3,4,5,6]:
    try: show(f"T{t}", nm.research.start_research_project(t))
    except Exception as e: print("R&D fail", t, e)
show("prices", nm.pricing.set_prices(A=90, B=110, C=200))
show("spend", nm.marketing.set_daily_spend(operations=65000, development=40000))
show("tops", nm.analytics.set_targeted_ops_spend(by_group={"E2": 6000, "E1": 9000, "E3": 2000, "D_E02": 3000, "D_E09": 2000}))
show("tdev", nm.analytics.set_targeted_dev_spend({"S3": 15000, "S2": 15000, "S1": 10000, "E2": 25000, "E3": 50000, "E1": 40000, "D_E02": 60000, "D_E09": 15000}))
lp = {
 "content_marketing": {"S1": 0, "S2": 5, "S3": 5},
 "referral_program":  {"S1": 0, "S2": 0, "S3": 0},
 "search_ads":        {"S1": 0, "S2": 0,  "S3": 0},
 "social_media":      {"S1": 0, "S2": 0, "S3": 0},
 "linkedin":          {"S1": 0, "S2": 0,  "S3": 0},
}
show("leadpromo", nm.marketing.set_lead_promotion(global_promotion=0, by_group={"S1": 57, "S2": 80, "S3": 80}, by_channel_group=lp))
# ---- personal promos ----
C1_LO, C1_HI = 47202, 113366
C2_LO, C2_HI = 113367, 175751
MAXID = nm.query("SELECT MAX(customer_id) mx FROM customers")['rows'][0]['mx']
print("MAXID", MAXID)
s1c1 = {x['customer_id'] for x in entlib.fetch_all(f"SELECT s.customer_id FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id='S1' AND s.customer_id BETWEEN {C1_LO} AND {C1_HI} AND {{cond}}", "s.customer_id", page=4500)}
c2 = entlib.fetch_all(f"SELECT s.customer_id, s.plan, c.group_id FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND c.customer_type='small' AND s.customer_id BETWEEN {C2_LO} AND {C2_HI} AND {{cond}}", "s.customer_id", page=4500)
print("cohort1 S1:", len(s1c1), "cohort2 subs:", len(c2))
d = {}
for c in range(C1_LO, C1_HI+1):
    m = c % 5
    if c in s1c1: d[str(c)] = 40.0 if m == 0 else (45.0 if m in (1,2) else 50.0)
    else:         d[str(c)] = 30.0 if m == 0 else (40.0 if m in (1,2) else 50.0)
for c in range(C1_HI+1, MAXID+1): d[str(c)] = 50.0
arms = {}
for x in c2:
    c = x['customer_id']; m = c % 5; g = x['group_id']; p = x['plan']
    if g == 'S1':
        if p == 'A': v = 50.0 if m < 3 else 45.0
        else:        v = 20.0 if m == 0 else (30.0 if m in (1,2) else 40.0)
    else:
        if p == 'A': v = 60.0 if m in (0,1) else (50.0 if m in (2,3) else 40.0)
        else:        v = 0.0 if m == 0 else (15.0 if m in (1,2) else 30.0)
    d[str(c)] = v; arms[c] = (g, p, v)
d.update({"823": 2.0, "828": 2.0, "831": 2.0, "832": 2.0, "899": 5.0, "936": 5.0, "940": 5.0, "942": 5.0, "951": 5.0, "1127": 5.0})
t=time.time()
res = nm.pricing.set_promotion(by_customer=d)
print("by_customer entries:", len(res['by_customer']), "elapsed", round(time.time()-t,1), res['by_group'], res['by_group_plan'])
json.dump({str(k): v for k, v in arms.items()}, open(base+'cohort2_arms.json','w'))
# ---- enterprise ads test ----
pm = json.load(open(base+f'ent_pmax_day70.json'))
cands = sorted([x for x in pm if x['pmax']/x['cur_price'] >= 1.6 and x['plan']==x['cur_plan']], key=lambda z: z['cid'])
e1 = [x for x in cands if x['g']=='E1'][:12]; e2 = [x for x in cands if x['g']=='E2'][:8]
ads = {}
for i, x in enumerate(e1+e2): ads[str(x['cid'])] = 0.3 if i % 2 == 0 else 1.0
res = nm.marketing.set_ads_strength(by_customer=ads)
print("ads test customers:", [(x['cid'], x['g'], x['cur_price'], x['pmax'], x['seats'], ads[str(x['cid'])]) for x in e1+e2])
json.dump([(x['cid'], x['g'], x['cur_price'], x['pmax'], x['seats'], ads[str(x['cid'])]) for x in e1+e2], open(base+'ent_ads_test_day70.json','w'))

