import json
import novamind_api as nm
def show(label, r): print("##", label, "->", json.dumps(r)[:300])
# restart any completed R&D tiers (one in progress per tier)
r = nm.query("SELECT tier, status FROM research_projects")
inprog = {x['tier'] for x in r['rows'] if x['status']=='in_progress'}
for t in range(1, 11):
    if t not in inprog:
        try: show(f"T{t}", nm.research.start_research_project(t))
        except Exception as e: print("R&D fail", t, e)
show("prices", nm.pricing.set_prices(A=90, B=110, C=230))
show("spend", nm.marketing.set_daily_spend(operations=65000, development=50000))
show("tops", nm.analytics.set_targeted_ops_spend(by_group={"E2": 6000, "E1": 10000, "E3": 2500, "D_E02": 5000, "D_E09": 2500}))
show("tdev", nm.analytics.set_targeted_dev_spend({"S3": 25000, "S2": 25000, "S1": 15000, "E2": 20000, "E3": 40000, "E1": 30000, "D_E02": 40000, "D_E09": 10000}))
ads = {
 "content_marketing": {"S1": 30000, "S2": 40000, "S3": 8000},
 "referral_program":  {"S1": 30000, "S2": 6000,  "S3": 25000},
 "social_media":      {"S2": 8000, "S3": 8000},
 "linkedin":          {"S2": 8000},
}
show("ads", nm.marketing.set_targeted_ad_spend(ads))
lp = {c: {"S1": 0, "S2": 0, "S3": 0} for c in ["content_marketing","referral_program","search_ads","social_media","linkedin"]}
show("leadpromo", nm.marketing.set_lead_promotion(global_promotion=0, by_group={"S1": 57, "S2": 80, "S3": 80}, by_channel_group=lp))

