import json, statistics
base='/workspace/local/workspace/run-ceobench/notes/'
ads = {a[0]: a for a in json.load(open(base+'ent_ads_test_day70.json'))}
old = {x['cid']: x for x in json.load(open(base+'ent_pmax_day70.json'))}
new = {x['cid']: x for x in json.load(open(base+'ent_pmax_day84.json'))}
rows = {'ads1.0': [], 'ads0.3': [], 'ctl': []}
for cid, x in new.items():
    if cid not in old or x['plan'] != old[cid]['plan'] or x['asked_plan'] != x['cur_plan']: continue
    ratio = x['pmax']/old[cid]['pmax']
    g = x['g']
    if cid in ads: rows['ads1.0' if ads[cid][5]==1.0 else 'ads0.3'].append((g, ratio, old[cid]['pmax'], x['pmax'], x['day']))
    else: rows['ctl'].append((g, ratio, old[cid]['pmax'], x['pmax'], x['day']))
for k, v in rows.items():
    for g in ('E1','E2'):
        r = [a[1] for a in v if a[0]==g]
        if r: print(k, g, 'n', len(r), 'median ratio new/old pmax', round(statistics.median(r),3), 'mean', round(sum(r)/len(r),3))
print(rows['ads1.0'][:10]); print(rows['ctl'][:6])
EOF

