"""Weekly config applier. Reads notes/week_cfg.json: ops, dev_global, tdev, tops, ads, leadpromo, in-app ads rules."""
import sys, json, time
sys.path.insert(0, '/workspace/local/workspace/run-ceobench/scripts')
import entlib
import novamind_api as nm
base='/workspace/local/workspace/run-ceobench/notes/'
W = json.load(open(base+'week_cfg.json'))
day = nm.vars.current_day
if W.get('rd_tiers'):
    r = nm.query("SELECT tier, status, project_id, quality_boost_applied q FROM research_projects")
    inprog = {x['tier'] for x in r['rows'] if x['status']=='in_progress'}
    done = [(x['project_id'], round(x['q'],3)) for x in r['rows'] if x['status']=='completed']
    print("R&D completed so far:", done)
    for t in W['rd_tiers']:
        if t not in inprog:
            try:
                x = nm.research.start_research_project(t); print("started T", t, x.get('project_id'), x.get('cost'))
            except Exception as e: print("R&D fail", t, e)
if 'tiers' in W: print("tiers", nm.pricing.set_model_tiers(**W['tiers']).get('current'))
if 'prices' in W: print("prices", nm.pricing.set_prices(**W['prices']).get('current'))
if 'capacity' in W: print("capacity", nm.infrastructure.set_capacity_tier(W['capacity']))
print("spend", nm.marketing.set_daily_spend(operations=W['ops'], development=W['dev_global']).get('current'))
print("tops total", nm.analytics.set_targeted_ops_spend(by_group=W['tops']).get('total_extra_per_day'))
print("tdev total", nm.analytics.set_targeted_dev_spend(W['tdev']).get('total_extra_per_day'))
print("ads total", nm.marketing.set_targeted_ad_spend(W['ads']).get('total_per_day'))
print("leadpromo", nm.marketing.set_lead_promotion(global_promotion=0, by_group=W['leadpromo']).get('by_group'))
A = W.get('inapp_ads')
if A:
    ads_c = {}
    ent = entlib.fetch_all(f"SELECT s.customer_id FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='large' AND s.status='subscribed' AND s.start_day <= {day-A['ent_min_age']} AND {{cond}}", "s.customer_id", page=4500)
    for x in ent: ads_c[str(x['customer_id'])] = A['ent_strength']
    n_ind = 0
    if A.get('ind_mod'):
        groups = ",".join("'%s'" % g for g in A['ind_groups'])
        ind = entlib.fetch_all(f"SELECT s.customer_id FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='small' AND c.group_id IN ({groups}) AND s.status='subscribed' AND s.customer_id >= 47202 AND s.customer_id % {A['ind_mod']} = 0 AND {{cond}}", "s.customer_id", page=4500)
        for x in ind: ads_c[str(x['customer_id'])] = A['ind_strength']
        n_ind = len(ind)
    r = nm.marketing.set_ads_strength(global_strength=A.get('global', 0.0), by_group=A.get('by_group', {}), by_customer=ads_c)
    print("in-app ads: enterprise", len(ent), "individual", n_ind, "by_group", r.get('by_group'))

