import novamind_api as nm
day = nm.vars.current_day; lo = day-6
q = lambda s: nm.query(s)['rows']
bl = ",".join(str(d % 30) for d in range(lo, day+1))
for g in ('S3','S1'):
    print(g, "plan B later-renewals this week by start-week and effective price bucket: cancelled / stayed")
    c = q(f"SELECT (s.start_day/7) w, ROUND(s.effective_price/10)*10 ep, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id='{g}' AND s.plan='B' AND s.status='cancelled' AND s.end_day>={lo} AND s.start_day<{day-36} GROUP BY 1,2")
    a = q(f"SELECT (s.start_day/7) w, ROUND(s.effective_price/10)*10 ep, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id='{g}' AND s.plan='B' AND s.status='subscribed' AND s.billing_day_mod30 IN ({bl}) AND s.start_day<{day-36} GROUP BY 1,2")
    cd = {(x['w'],x['ep']): x['n'] for x in c}; ad = {(x['w'],x['ep']): x['n'] for x in a}
    for k in sorted(set(cd)|set(ad)):
        t = cd.get(k,0)+ad.get(k,0)
        if t >= 150: print("   start_wk", k[0], "price~", k[1], "cancelled", cd.get(k,0), "stayed", ad.get(k,0), f"{cd.get(k,0)/t*100:.0f}%")
r = q(f"SELECT post_id, day, substr(content,1,230) c FROM social_media_posts WHERE day>={lo} AND (content LIKE '%competitor%' OR content LIKE '%launch%' OR content LIKE '%rival%' OR content LIKE '%announc%') ORDER BY post_id DESC LIMIT 8")
for x in r: print(x['day'], x['c'].replace('\n',' '))

