import novamind_api as nm, collections
day = nm.vars.current_day; lo = day-6
q = lambda s: nm.query(s)['rows']
bl = ",".join(str(d % 30) for d in range(lo, day+1))
mult = {0: 0.75, 1: 1.0, 2: 1.3}
c = q(f"SELECT c.group_id g, s.plan p, (s.customer_id%3) m, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id LIKE 'D_S%' AND s.status='cancelled' AND s.end_day>={lo} AND s.start_day>={day-37} GROUP BY 1,2,3")
a = q(f"SELECT c.group_id g, s.plan p, (s.customer_id%3) m, COUNT(*) n, ROUND(AVG(s.effective_price),1) ep FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id LIKE 'D_S%' AND s.status='subscribed' AND s.billing_day_mod30 IN ({bl}) AND s.start_day BETWEEN {day-37} AND {day-30} GROUP BY 1,2,3")
cd = {(x['g'],x['p'],x['m']): x['n'] for x in c}
out = collections.defaultdict(list)
for x in a:
    k = (x['g'],x['p'],x['m']); cn = cd.get(k,0); t = cn + x['n']
    if t >= 300: out[(x['g'],x['p'])].append((x['m'], x['ep'], round(cn/t*100), round(x['ep']*x['n']/t,1), t))
for k in sorted(out):
    print(k, " | ".join(f"x{mult[m]}: ${ep} churn {ch}% rev/orig ${rv} (n{t})" for m, ep, ch, rv, t in sorted(out[k])))

